// Spawn the exact OpenClaw-registered gbrain MCP server and drive it over stdio JSON-RPC.
import { spawn } from 'node:child_process';
const steps = JSON.parse(process.argv[2]);
const p = spawn('/harness-state/.bun/bin/gbrain', ['serve','--surface','starter','--advertise','verbs'],
  { env: { ...process.env, GBRAIN_HOME: '/harness-state' }, cwd: '/' , stdio: ['pipe','pipe','pipe']});
let buf = ''; const pending = new Map(); let id = 0;
p.stdout.on('data', d => { buf += d; let i; while ((i = buf.indexOf('\n')) >= 0) { const line = buf.slice(0,i); buf = buf.slice(i+1);
  if (!line.trim()) continue; let m; try { m = JSON.parse(line); } catch { continue; }
  if (m.id != null && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } } });
p.stderr.on('data', d => process.stderr.write('[serve stderr] ' + d));
const rpc = (method, params) => new Promise(r => { const i = ++id; pending.set(i, r); p.stdin.write(JSON.stringify({jsonrpc:'2.0', id:i, method, params})+'\n'); });
const init = await rpc('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'openclaw-smoke', version: '1' } });
console.log('initialize ->', init.result?.serverInfo);
p.stdin.write(JSON.stringify({jsonrpc:'2.0', method:'notifications/initialized'})+'\n');
const tl = await rpc('tools/list', {});
console.log('tools ->', tl.result?.tools?.map(t => t.name).join(', '));
for (const [name, args] of steps) {
  const r = await rpc('tools/call', { name, arguments: args });
  const txt = r.error ? JSON.stringify(r.error) : (r.result?.content || []).map(c => c.text).join('\n');
  console.log(`\n== ${name} ${r.result?.isError ? '(isError)' : ''}\n` + txt.slice(0, 1500));
}
p.kill(); process.exit(0);

